pub struct Lines<'a> { it: std::str::Lines<'a>, n: usize }
impl<'a> Lines<'a> {
  pub fn new(s: &'a str) -> Self { Self { it: s.lines(), n: 0 } }
  pub fn next_line(&mut self) -> Option<(usize, &'a str)> { let l = self.it.next()?; self.n += 1; Some((self.n, l.trim_end())) }
  pub fn err(&self, msg: &str) -> ParseError { ParseError { line: self.n, msg: msg.into() } }
}
